```php
/**
 * Read and annotate, never write (issue #33, findings SP-03 + ST-01; follow-up
 * of #25/WA-02): the same two order caps that open the native editor and its
 * note AJAX also pass Woo's own nonce and capability checks on every
 * record-mutation surface — the editor save (contact data, status, order
 * actions; both the posts store and HPOS pipelines), the orders-list bulk
 * actions (status changes, trash/delete, personal-data removal), the quick
 * status AJAX whose nonce Woo itself renders for this role (order preview
 * modal), the REST orders API (wc_rest_check_post_permissions() maps 'edit'
 * onto the same edit_others cap) and the note-deletion AJAX. The guards below
 * close each surface server-side for order-limited staff AFTER Woo's own
 * checks, so a valid request with valid nonces is still denied — every denial
 * is attributable to permissions, never to a missing or invalid nonce; the UI
 * is reduced so it never offers a denied action; administrators and managers
 * (manage_woocommerce) keep Woo's native behavior everywhere. Ampliar el
 * alcance de Ventas es una decisión humana aparte; que el editor lo permita no
 * constituye autorización.
 */

/** The uniform denial: consulta-only, with the operation class named. */
function fpw_die_sales_read_only(): void {
	wp_die( 'Las solicitudes de cotización son de solo consulta para tu rol: puedes buscarlas, leerlas y agregar notas de ventas privadas, pero no modificar sus datos ni su estado.', '', array( 'response' => 403 ) );
}

/** True when the id belongs to a shop_order record (the posts-store surface). */
function fpw_is_shop_order_post( int $post_id ): bool {
	$post = $post_id ? get_post( $post_id ) : null;
	return $post && 'shop_order' === $post->post_type;
}

/**
 * Front door (admin_init runs before any save machinery): the quick-status and
 * note-deletion AJAX, the posts-store editor save (WP would write the record
 * row itself — including status — before Woo's save hooks fire) and the HPOS
 * editor save never reach their handlers for order-limited staff. The kept
 * surfaces (list, search, editor reads, the private-note AJAX) pass untouched.
 */
function fpw_deny_sales_record_mutation(): void {
	if ( ! fpw_is_order_limited_staff() ) { return; }
	$ajax_action = wp_doing_ajax() ? (string) ( $_REQUEST['action'] ?? '' ) : '';
	if ( in_array( $ajax_action, array( 'woocommerce_mark_order_status', 'woocommerce_delete_order_note' ), true ) ) {
		fpw_die_sales_read_only();
	}
	if ( 'editpost' === ( $_POST['action'] ?? '' ) && fpw_is_shop_order_post( absint( $_POST['post_ID'] ?? 0 ) ) ) {
		fpw_die_sales_read_only();
	}
	if ( 'edit_order' === ( $_POST['action'] ?? '' ) && str_starts_with( (string) ( $_GET['page'] ?? '' ), 'wc-orders' ) ) {
		fpw_die_sales_read_only();
	}
}
add_action( 'admin_init', 'fpw_deny_sales_record_mutation', 0 );

/**
 * The deep backstop inside Woo's own save pipeline (both storage modes run it
 * after their nonce + capability checks, before any metabox save at priority
 * 10+): an order-limited editor save dies before anything is written. Covers
 * every route that reaches the metabox pipeline, including the order actions
 * it dispatches (resends, downloads).
 */
function fpw_deny_sales_order_save(): void {
	if ( fpw_is_order_limited_staff() ) { fpw_die_sales_read_only(); }
}
add_action( 'woocommerce_process_shop_order_meta', 'fpw_deny_sales_order_save', 0 );

/**
 * Bulk mutations on the orders list (status changes, trash/delete/untrash,
 * personal-data removal) pass Woo's own handler in both storage modes through
 * this filter, after its nonce + capability checks: denied for order-limited
 * staff before any order is touched.
 */
function fpw_deny_sales_bulk_actions( $ids ) {
	if ( fpw_is_order_limited_staff() ) { fpw_die_sales_read_only(); }
	return $ids;
}
add_filter( 'woocommerce_bulk_action_ids', 'fpw_deny_sales_bulk_actions', 0 );

/**
 * The REST orders API maps 'edit' and 'batch' onto the same edit_others cap
 * this role holds for the admin screens — without this guard a cookie-auth'd
 * PUT /wc/v3/orders/{id} (or a batch update) would rewrite the record. All
 * mutating REST contexts are outside the consulta scope; read contexts pass
 * through unchanged for everyone.
 */
function fpw_deny_sales_rest_mutation( $permission, $context ) {
	if ( fpw_is_order_limited_staff() && in_array( $context, array( 'create', 'edit', 'delete', 'batch' ), true ) ) {
		return false;
	}
	return $permission;
}
add_filter( 'woocommerce_rest_check_permissions', 'fpw_deny_sales_rest_mutation', 10, 2 );
```

